import (
  "net/http"
  "acme/payments/internal"
)

func main() {
  http.HandleFunc("/authorize", internal.Authorize)
  http.ListenAndServe(":8080", nil)
}

package internal

func Authorize(w http.ResponseWriter, r *http.Request) {
  // authorize via gateway
  w.WriteHeader(http.StatusOK)
}

package internal

import (
  "errors"
  "time"
)

func withRetry(req Request) error {
  for i := 0; i < 3; i++ {
    if err := req.Do(); err == nil {
      return nil
    }
    time.Sleep(time.Duration(1<<uint(i)) * time.Second)
  }
  return errors.New("gateway unavailable")
}

package internal

var keys = map[string]bool{}

func Idempotent(key string, fn func()) {
  if keys[key] {
    return
  }
  keys[key] = true
  fn()
}

package ledger

type Event struct {
  Type     string
  Amount   int64
  Currency string
}

export default function Home() {
  return <ProductGrid />
}

export async function getServerSideProps(ctx) {
  const session = await getSession(ctx)
  if (!session) return { redirect: { destination: '/api/auth/signin' } }
  return { props: {} }
}

export default function Checkout() {
  return <CartSummary />
}

export function ProductGrid({ items }: { items: Item[] }) {
  return (
    <ul>
      {items.map((it) => (
        <li key={it.id}><Price value={it.price} suppressHydrationWarning /></li>
      ))}
    </ul>
  )
}

import { useFocusTrap } from '../hooks/useFocusTrap'

export function CartDrawer({ open }: { open: boolean }) {
  const trap = useFocusTrap()
  if (!open) return null
  return (
    <div role="dialog" aria-modal="true" aria-label="Cart" ref={trap}>
      <CartItems />
    </div>
  )
}

